/* ===================== EXPRESSION PORTRAITS (from the character expression charts, pixelated to 84px / 48 colours) ===================== */
const XPORT={"v":{"neutral":"data:image/webp;base64,","calm":"data:image/webp;base64,","angry":"data:image/webp;base64,","surprised":"data:image/webp;base64,","stern":"data:image/webp;base64,","smile":"data:image/webp;base64,","shout":"data:image/webp;base64,","fluster":"data:image/webp;base64,","content":"data:image/webp;base64,"},"m":{"neutral":"data:image/webp;base64,","talk":"data:image/webp;base64,","annoyed":"data:image/webp;base64,","surprised":"data:image/webp;base64,","cry":"data:image/webp;base64,","smug":"data:image/webp;base64,","shout":"data:image/webp;base64,","fluster":"data:image/webp;base64,","content":"data:image/webp;base64,"},"r":{"neutral":"data:image/webp;base64,","grin":"data:image/webp;base64,","angry":"data:image/webp;base64,","surprised":"data:image/webp;base64,","cry":"data:image/webp;base64,","smirk":"data:image/webp;base64,","shout":"data:image/webp;base64,","fluster":"data:image/webp;base64,","laugh":"data:image/webp;base64,"},"a":{"neutral":"data:image/webp;base64,","flirt":"data:image/webp;base64,","annoyed":"data:image/webp;base64,","surprised":"data:image/webp;base64,","cry":"data:image/webp;base64,","smirk":"data:image/webp;base64,","shout":"data:image/webp;base64,","fluster":"data:image/webp;base64,","laugh":"data:image/webp;base64,"}};
const XPIMG={};for(const k in XPORT)for(const n in XPORT[k]){const i=new Image();i.src=XPORT[k][n];XPIMG[k+n]=i}
function xPickExpr(k,t){t=String(t||'');const L=t.toLowerCase();const caps=(t.match(/\b[A-Z]{3,}\b/g)||[]).filter(w=>!/^(DON|NOT|CRT|TV|K9|EAT|OK|DO)$/.test(w)).length;
 const F={v:{angry:'angry',shout:'shout',fluster:'fluster',sad:'stern',surprised:'surprised',warm:'content',laugh:'smile',dark:'stern',idle:['neutral','calm','neutral']},
  m:{angry:'annoyed',shout:'shout',fluster:'fluster',sad:'cry',surprised:'surprised',warm:'content',laugh:'smug',dark:'neutral',idle:['neutral','talk','talk']},
  r:{angry:'angry',shout:'shout',fluster:'fluster',sad:'cry',surprised:'surprised',warm:'smirk',laugh:'laugh',dark:'neutral',idle:['neutral','smirk','grin']},
  a:{angry:'annoyed',shout:'shout',fluster:'fluster',sad:'cry',surprised:'surprised',warm:'flirt',laugh:'laugh',dark:'neutral',idle:['neutral','smirk','flirt']}}[k];if(!F)return'neutral';
 if(S&&S.dark&&k==='m'&&/sorry|can’t|can't|scared|alone|please|hurt|don’t go|stay/.test(L))return F.sad;
 if(/\b(shut up|hate|idiot|stupid|furious|how dare|coward|i will not be kind|bastard|rude)\b/.test(L))return F.angry;
 if(caps>=1||/!!|\?!|!\?/.test(t))return F.shout;
 if(/\b(love|cute|kiss|marry|beautiful|pretty|handsome|blush|date|husband|wife|babe|darlin)/.test(L))return F.fluster;
 if(/\b(sorry|miss (you|him|her)|crying|tears|funeral|grave|dead|lost|alone|gone)\b/.test(L))return F.sad;
 if(/^(wait|what|huh|oh)\b|\?$/.test(L.trim())&&L.length<70)return F.surprised;
 if(/(haha|lol|hehe|:\)|\bheh\b|ha!|😂|🙂)/.test(L))return F.laugh;
 if(/\b(thank|glad|good girl|good boy|proud|happy|home|warm|safe|stay|sweetheart|pal)\b/.test(L))return F.warm;
 if(/\b(nice|good|of course|sure)\b/.test(L))return k==='v'?'smile':F.laugh;
  return'neutral'}
const _dpPort=drawPortrait;drawPortrait=function(cv2,k,blink){if(!XPORT[k]||!cv2)return _dpPort(cv2,k,blink);const ex=cv2.dataset.ex||'neutral';
 const im=XPIMG[k+ex]||XPIMG[k+'neutral'];if(!im||!im.complete||!im.naturalWidth)return _dpPort(cv2,k,blink);const N=im.naturalWidth;if(cv2.width!==N){cv2.width=N;cv2.height=N}const g=cv2.getContext('2d');g.imageSmoothingEnabled=false;g.drawImage(im,0,0,N,N);
 if(S&&S.dark){g.fillStyle='rgba(60,0,15,.16)';g.fillRect(0,0,N,N)}};
const _showPort=showL;showL=function(){const r=_showPort.apply(this,arguments);if(dlg&&dlg.pt&&XPORT[dlg.k]){dlg.pt.dataset.ex=xPickExpr(dlg.k,dlg.full);drawPortrait(dlg.pt,dlg.k,false)}return r};
const _askPort=ask;ask=function(who,text,opts){const r=_askPort.apply(this,arguments);const k=whoKey(who);if(XPORT[k]){const pts=ui.querySelectorAll('.dlg .pt');const pt=pts[pts.length-1];if(pt){pt.dataset.ex=xPickExpr(k,text);drawPortrait(pt,k,false)}}return r};
(function(){const st=document.createElement('style');st.textContent='.dlg .pt{width:clamp(64px,14vw,124px)!important;image-rendering:pixelated}';document.head.appendChild(st)})();
const _wkPort=whoKey;whoKey=function(w){const k=_wkPort(w);if(k==='x'&&w&&/^angel\b/i.test(String(w).trim()))return'a';return k};
